import sys

def reconstruct_binary_string(n0, n1, n2):
    if n2 > 0:
        result = ['1'] * (n2 + 1)
        n1 -= n2
    else:
        result = []

    if n1 > 0:
        if len(result) == 0:
            result.append('1')
        for _ in range(n1 // 2):
            result.extend(['0', '1'])
        if n1 % 2 == 1:
            result.append('0')

    if n0 > 0:
        if len(result) == 0:
            result = ['0']
        for _ in range(n0 - 1):
            result.append('0')

    return ''.join(result)

input = sys.stdin.read().split()
index = 0
t = int(input[index])
index += 1
results = []
for _ in range(t):
    n0 = int(input[index])
    n1 = int(input[index + 1])
    n2 = int(input[index + 2])
    index += 3
    results.append(reconstruct_binary_string(n0, n1, n2))

print('\n'.join(results))
